SET client_encoding = 'UTF8';

CREATE TABLE hlstats_Actions (
  id integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  game varchar(10) NOT NULL DEFAULT 'valve',
  code varchar(128) NOT NULL DEFAULT '',
  reward_player integer NOT NULL DEFAULT 10,
  reward_team integer NOT NULL DEFAULT 0,
  team varchar(128) NOT NULL DEFAULT '',
  description varchar(255),
  for_PlayerActions varchar(1) NOT NULL DEFAULT '0' CHECK (for_PlayerActions IN ('0','1')),
  for_PlayerPlayerActions varchar(1) NOT NULL DEFAULT '0' CHECK (for_PlayerPlayerActions IN ('0','1')),
  for_TeamActions varchar(1) NOT NULL DEFAULT '0' CHECK (for_TeamActions IN ('0','1')),
  for_WorldActions varchar(1) NOT NULL DEFAULT '0' CHECK (for_WorldActions IN ('0','1')),
  count bigint NOT NULL DEFAULT 0,
  PRIMARY KEY (id)
);
CREATE UNIQUE INDEX hlstats_Actions_game ON hlstats_Actions (game, code);
CREATE INDEX hlstats_Actions_code ON hlstats_Actions (code);
CREATE TABLE hlstats_Awards (
  awardId integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
