  game varchar(10) NOT NULL DEFAULT 'valve',
  code varchar(128) NOT NULL DEFAULT '',
  name varchar(255) NOT NULL DEFAULT '',
  verb varchar(255) NOT NULL DEFAULT '',
  d_winner_id integer,
  d_winner_count integer,
  PRIMARY KEY (awardId)
);
CREATE UNIQUE INDEX hlstats_Awards_game ON hlstats_Awards (game, code);
CREATE INDEX hlstats_Awards_name ON hlstats_Awards (name);
